 * `new_pcb` and return the user virtual address of the argv array.  The page
 * is filled in through the kernel's direct mapping, which is reachable no
 * matter which address space is currently installed.  `*argc_io` is updated
 * to the number of arguments that actually fit, so that the a0 handed to the
 * new process can never disagree with the array a1 points at.
 */
static uintptr_t init_user_stack(pcb_t *new_pcb, int *argc_io, char *argv[])
{
