     * only this page is reachable through `top_kva`.  Measure first and drop
     * arguments from the tail until the strings, the argv array, the
     * alignment slack and a little room for the callee all fit. */
    uintptr_t budget = PAGE_SIZE - 64;
    uintptr_t need = 0;
    for (i = 0; i < argc; i++) {
        len[i] = strlen(argv[i]) + 1;
        need += (uintptr_t)len[i];
    }
