int do_kill(pid_t pid)
{
    disable_preempt();

    pcb_t *victim = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            victim = &pcb[i];
            break;
        }
    }
    if (victim == NULL || victim->status == TASK_EXITED ||
        victim->status == TASK_ZOMBIE || victim->status == TASK_KILLED) {
        enable_preempt();
        return 0;
    }

    if (victim == current_running[cpu_id]) {
        /* killing ourselves is just an exit */
        enable_preempt();
        do_exit();
        return 1;
    }

    release_resources(victim);

    if (victim->status == TASK_RUNNING) {
        /* it is running on the other hart, and its page table is live there:
         * flag it and let that hart finish the teardown when it reschedules */
        victim->status = TASK_KILLED;
    } else {
        free_process_user_page(victim->pgdir);
        victim->pgdir = (PTE*)PGDIR_PA;
        reclaim_pcb(victim);
    }

    enable_preempt();
    return 1;
}

